import{_ as l,a0 as i,w as c,s as p,ao as t,I as d,x as s,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"FreeDOS 配置指南 | LCTT x X-CMD","titleTemplate":false,"description":"FreeDOS 配置指南 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"FreeDOS 配置指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"FreeDOS 配置指南 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20210609 Configure FreeDOS in plain text","title":"FreeDOS 配置指南","tag":"202112","desc":""},"relativePath":"202112/20210609 Configure FreeDOS in plain text.md","filePath":"[post].md"}'),r={name:"202112/20210609 Configure FreeDOS in plain text.md"};function S(E,e,O,D,C,F){const o=i("Link");return c(),p("div",null,[e[15]||(e[15]=t(`<h1 id="freedos-配置指南" tabindex="-1">FreeDOS 配置指南 <a class="header-anchor" href="#freedos-配置指南" aria-label="Permalink to “FreeDOS 配置指南”">​</a></h1><blockquote><p>學習如何使用 FDCONFIG.SYS 來配置 FreeDOS 。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202112/08/124646wahca435y60acpha.jpg" alt=""></p><p>FreeDOS 是主配置文件是在根目錄中的名稱為 <code>FDCONFIG.SYS</code> 的文件。這個文件包含一系列的行，每行都設置一個諸如 <code>LASTDRIVE=Z</code> 或 <code>FILES=40</code> 的值。例如，在 FreeDOS 1.3 RC4 中的默認 <code>FDCONFIG.SYS</code> ，看起來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SET DOSDIR=C:\\FDOS</span></span>
<span class="line"><span></span></span>
<span class="line"><span>!COUNTRY=001,858,C:\\FDOS\\BIN\\COUNTRY.SYS</span></span>
<span class="line"><span>!LASTDRIVE=Z</span></span>
<span class="line"><span>!BUFFERS=20</span></span>
<span class="line"><span>!FILES=40</span></span>
<span class="line"><span>!MENUCOLOR=7,0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MENUDEFAULT=1,5</span></span>
<span class="line"><span>MENU 1 - Load FreeDOS with JEMMEX, no EMS (most UMBs), max RAM free</span></span>
<span class="line"><span>MENU 2 - Load FreeDOS with JEMM386 (Expanded Memory)</span></span>
<span class="line"><span>MENU 3 - Load FreeDOS low with some drivers (Safe Mode)</span></span>
<span class="line"><span>MENU 4 - Load FreeDOS without drivers (Emergency Mode)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>12?DOS=HIGH</span></span>
<span class="line"><span>12?DOS=UMB</span></span>
<span class="line"><span>12?DOSDATA=UMB</span></span>
<span class="line"><span>1?DEVICE=C:\\FDOS\\BIN\\JEMMEX.EXE NOEMS X=TEST I=TEST NOVME NOINVLPG</span></span>
<span class="line"><span>234?DEVICE=C:\\FDOS\\BIN\\HIMEMX.EXE</span></span>
<span class="line"><span>2?DEVICE=C:\\FDOS\\BIN\\JEMM386.EXE X=TEST I=TEST I=B000-B7FF NOVME NOINVLPG</span></span>
<span class="line"><span>34?SHELL=C:\\FDOS\\BIN\\COMMAND.COM C:\\FDOS\\BIN /E:1024 /P=C:\\FDAUTO.BAT</span></span>
<span class="line"><span>12?SHELLHIGH=C:\\FDOS\\BIN\\COMMAND.COM C:\\FDOS\\BIN /E:1024 /P=C:\\FDAUTO.BAT</span></span></code></pre></div><p>但是，這些指令行都表示什麼意思？為什麼一些指令行有一個問號（<code>?</code>）或一個歎號（<code>!</code>），而其它的命令列卻沒有？</p><h3 id="一個簡單的配置" tabindex="-1">一個簡單的配置 <a class="header-anchor" href="#一個簡單的配置" aria-label="Permalink to “一個簡單的配置”">​</a></h3><p>讓我們從一個簡單的配置開始，像這樣，我們就可以看到我們的配置做了什麼。做出這個非常簡單的 <code>FDCONFIG.SYS</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LASTDRIVE=Z</span></span>
<span class="line"><span>BUFFERS=20</span></span>
<span class="line"><span>FILES=40</span></span>
<span class="line"><span>DEVICE=C:\\FDOS\\BIN\\HIMEMX.EXE</span></span>
<span class="line"><span>SHELL=C:\\FDOS\\BIN\\COMMAND.COM C:\\FDOS\\BIN /E:1024 /P=C:\\FDAUTO.BAT</span></span></code></pre></div><p>這個配置文件僅包含幾個指令：</p><ol><li><code>LASTDRIVE=Z</code></li><li><code>BUFFERS=20</code></li><li><code>FILES=40</code></li><li><code>DEVICE=C:\\FDOS\\BIN\\HIMEMX.EXE</code></li><li><code>SHELL=C:\\FDOS\\BIN\\COMMAND.COM C:\\FDOS\\BIN /E:1024 /P=C:\\FDAUTO.BAT</code></li></ol><p>第一行指令告訴 FreeDOS 在存儲器中保留多少驅動器字母。（DOS 使用字母來表示附屬於系統的每個驅動器，<code>LASTDRIVE=Z</code> 表示預留從 <code>A</code> 到 <code>Z</code> 的所有驅動器字母）。 <code>LASTDRIVE</code> 會影響系統可以識別的 <em>邏輯驅動器</em> 的數量。你可能沒有任何的邏輯驅動器；FreeDOS 安裝器不會默認設置這些邏輯驅動器。在任何情況下，在任何 FreeDOS 系統上設置 <code>LASTDRIVE=Z</code> 都是沒有害處的。</p><p><code>BUFFERS</code> 行設置文件緩衝區預留存儲器。<em>緩衝區</em> 有助於加速某些需要存儲空間的進程，例如複製文件。如果你為 <code>BUFFERS</code> 設置一個較大的值，那麼 FreeDOS 將預留更多的存儲器。同理反之。大多數的用户將會設置其為 <code>BUFFERS=20</code> 或 <code>BUFFERS=40</code> ，取決於他們在系統上讀寫文件的頻率。</p><p><code>FILES</code> 設置決定 DOS 允許你一次打開多少文件。如果你運行的一個應用程序需要一次打開很多文件，例如打開一個譜系資料庫，你可能需要為 <code>FILES</code> 設置一個較大的值。對於大多數的用户來説，<code>FILES=40</code> 是一個合理的值。</p><p><code>DEVICE</code> 是一個特殊的指令，用於加載 <em>設備驅動器</em> 。DOS 需要針對某些硬件或配置文件的設備驅動器。這行 <code>DEVICE=C:\\FDOS\\BIN\\HIMEMX.EXE</code> 來加載 <em>HimemX</em> 設備驅動，這樣，DOS 可以利用超出前 640 KB 的擴展存儲器。</p><p>最後的指令行告訴 FreeDOS 的內核在哪裏找到命令列 shell 。默認情況下，內核將從 <code>COMMAND.COM</code> 開始查找 shell ，但是你可以使用 <code>SHELL</code> 指令來更改它。在這個示例中， <code>SHELL=C:\\FDOS\\BIN\\COMMAND.COM</code> 説明 shell 是 <code>COMMAND.COM</code> 程序，位於 <code>C</code> 驅動器上的 <code>\\FDOS\\BIN</code> 目錄之中。</p><p>在 <code>SHELL</code> 結尾處的其它文件表示選項為 <code>COMMAND.COM</code> 的 shell 。FreeDOS 的 <code>COMMAND.COM</code> 支持一些啓動選項來修改它的行為，包括：</p><ul><li><code>C:\\FDOS\\BIN</code>：<code>COMMAND.COM</code> 程序的完整的路徑</li><li><code>/E:1024</code>：環境（<code>E</code>）大小，以字節為單位。<code>/E:1024</code> 告訴 <code>COMMAND.COM</code> 來預留 1024 字節，或者説是 1 KB ，來存儲它的環境變量。</li><li><code>/P=C:\\FDAUTO.BAT</code>：<code>/P</code> 選項表示 shell 是一個永久性的（<code>P</code>）shell ，因此用户不能通過輸入 <code>EXIT</code> 來退出 shell（附加文本 <code>=C:\\FDAUTO.BAT</code> 告訴 <code>COMMAND.COM</code> 在啓動時執行 <code>C:\\FDAUTO.BAT</code> 文件，而不再執行默認的 <code>AUTOEXEC.BAT</code> 文件）</li></ul><p>通過這個簡單的配置文件，你應該能夠理解 FreeDOS 1.3 RC4 安裝的 <code>FDCONFIG.SYS</code> 文件中的一些東西。</p><h3 id="啓動菜單" tabindex="-1">啓動菜單 <a class="header-anchor" href="#啓動菜單" aria-label="Permalink to “啓動菜單”">​</a></h3><p>FreeDOS 支持一種有序的功能：在一個系統上使用多個配置文件，使用一個“啓動菜單”來選擇你想要的配置。<code>FDCONFIG.SYS</code> 文件包含一些定義菜單的行:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>!MENUCOLOR=7,0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MENUDEFAULT=1,5</span></span>
<span class="line"><span>MENU 1 - Load FreeDOS with JEMMEX, no EMS (most UMBs), max RAM free</span></span>
<span class="line"><span>MENU 2 - Load FreeDOS with JEMM386 (Expanded Memory)</span></span>
<span class="line"><span>MENU 3 - Load FreeDOS low with some drivers (Safe Mode)</span></span>
<span class="line"><span>MENU 4 - Load FreeDOS without drivers (Emergency Mode)</span></span></code></pre></div><p><code>MENUCOLOR</code> 指令定義啓動菜單的文本顏色和背景顏色。這些值通常在 0 到 7 的範圍之內, 並代表這些顏色：</p><ul><li>0 黑色</li><li>1 藍色</li><li>2 綠色</li><li>3 品藍</li><li>4 紅色</li><li>5 品紅</li><li>6 棕色</li><li>7 白色</li></ul><p>因此，<code>MENUCOLOR=7,0</code> 的定義意味着顯示一個黑色背景（<code>0</code>）白色文本（<code>7</code>）的菜單。如果你想使用一個藍色背景白色文本，你可以將其定義為 <code>MENUCOLOR=7,1</code> 。</p><p>在行頭部的歎號（<code>!</code>）意味着：不管你選擇哪個菜單，這個指令都將會執行。</p><p><code>MENUDEFAULT=1,5</code> 行告訴內核等待用户多長時間來選擇啓動菜單項，或者如果用户沒有選擇的話，使用那個默認菜單項。<code>MENUDEFAULT=1,5</code> 標示着系統將等待 <code>5</code> 秒鐘；如果用户不在這段時間內嘗試選擇一個菜單的話，內核將選擇啓動菜單 “1” 。</p><p><img src="https://opensource.com/sites/default/files/uploads/boot-menu.png" alt="boot menu" title="The boot menu waits for 5 seconds before assuming menu item 1"></p><p>在其後的 <code>MENU</code> 行至不同啓動菜單配置的標籤。它們是按順序排列的，因此，菜單項目 “1” 是第一個，接下來的 “2” 是第二個，以此類推。</p><p><img src="https://opensource.com/sites/default/files/uploads/menu-select4.png" alt="menu select 4" title="Use the arrow keys to select a boot menu configuration"></p><p>在 <code>FDCONFIG.SYS</code> 中的接下來的一行中，你將在一個問號（<code>?</code>）前看到一些數字。這標示“針對這幾個數字的啓動菜單項，使用這行命令”。例如，如果用户選擇啓動菜單項 “2”、“3” 或 “4” 的話，那麼帶有 <code>234?</code> 的這行命令才將加載 HimemX 設備驅動器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>234?DEVICE=C:\\FDOS\\BIN\\HIMEMX.EXE</span></span></code></pre></div><p>這裏有很多方法來使用 <code>FDCONFIG.SYS</code> 以配置你的 FreeDOS 系統。我們在這裏只介紹基本的東西，最重用的方法是定義你的 FreeDOS 內核設置。更多的信息，探索 FreeDOS 幫助系統（在命令列中輸入 <code>HELP</code>）來學習如何使用 FreeDOS 的 <code>FDCONFIG.SYS</code> 選項：</p><ul><li><code>SWITCHES</code>：啓動時處理過程行為</li><li><code>REM</code> 和 <code>;</code>：註釋（在 <code>FDCONFIG.SYS</code> 中將被忽略）</li><li><code>MENUCOLOR</code>：啓動菜單文本顏色和背景顏色</li><li><code>MENUDEFAULT</code>：啓動菜單默認值</li><li><code>MENU</code>：啓動菜單選項</li><li><code>ECHO</code> 和 <code>EECHO</code>：顯示信息</li><li><code>BREAK</code>：設置打開或關閉擴展的 <code>Ctrl+C</code> 檢查</li><li><code>BUFFERS</code> 或 <code>BUFFERSHIGH</code>：分配多少磁盤緩衝區</li><li><code>COUNTRY</code>：設置國際化行為</li><li><code>DOS</code>：告訴 FreeDOS 內核如何將其自身加載到存儲器之中</li><li><code>DOSDATA</code>：告訴 FreeDOS 加載內核到上位存儲器之中</li><li><code>FCBS</code>：設置文件控制塊（FCB）的數量</li><li><code>KEYBUF</code>：在存儲器中重新指定鍵盤緩衝區</li><li><code>FILES</code> 或 <code>FILESHIGH</code>：一次可以打開多少個文件</li><li><code>LASTDRIVE</code> 或 <code>LASTDRIVEHIGH</code>：設置可以使用的最後一個驅動器字母</li><li><code>NUMLOCK</code>：設置打開或關閉鍵盤數字鎖</li><li><code>SHELL</code>、<code>SHELLHIGH</code> 或 <code>COMMAND</code>：設置命令列 shell</li><li><code>STACKS</code> 或 <code>STACKSHIGH</code>：添加堆棧以處理硬件中斷</li><li><code>SWITCHAR</code>：重新定義命令列選項開關字符</li><li><code>SCREEN</code>：設置在屏幕上的行數</li><li><code>VERSION</code>：設置向程序報告的 DOS 版本</li><li><code>IDLEHALT</code>：激活節能功能，在某些系統上有用</li><li><code>DEVICE</code> 和 <code>DEVICEHIGH</code>：加載一個驅動程序到存儲器之中</li><li><code>INSTALL</code> 和 <code>INSTALLHIGH</code>：加載一個 “存儲器駐留”（TSR）程序</li><li><code>SET</code>：設置一個 DOS 環境變量</li></ul><h3 id="以純文本方式配置-freedos" tabindex="-1">以純文本方式配置 FreeDOS <a class="header-anchor" href="#以純文本方式配置-freedos" aria-label="Permalink to “以純文本方式配置 FreeDOS”">​</a></h3><p>像 Linux 和 BSD 一樣，FreeDOS 配置以純文本的方式進行。不需要特殊指定的編輯工具，因此，深入研究，看看哪些選項最適合你。它很簡單，但是功能很強大！</p><hr>`,37)),d("p",null,[e[1]||(e[1]=s("via: ",-1)),a(o,{href:"https://opensource.com/article/21/6/freedos-fdconfigsys"},{default:n(()=>[...e[0]||(e[0]=[s("https://opensource.com/article/21/6/freedos-fdconfigsys",-1)])]),_:1})]),d("p",null,[e[6]||(e[6]=s("作者：",-1)),a(o,{href:"https://opensource.com/users/jim-hall"},{default:n(()=>[...e[2]||(e[2]=[s("Jim Hall",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),a(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),a(o,{href:"https://github.com/robsean"},{default:n(()=>[...e[4]||(e[4]=[s("robsean",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),a(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),d("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),a(o,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const N=l(r,[["render",S]]);export{I as __pageData,N as default};
